import { rawQuery } from '../cloudflare/d1';

// Migrations generated by drizzle-kit (`pnpm db:generate`), bundled as text.
// The default drizzle migrator reads from the filesystem and therefore doesn't work on Workers.
const migrations = import.meta.glob<string>('/drizzle/*.sql', {
	query: '?raw',
	import: 'default',
	eager: true
});

export async function migrate() {
	await rawQuery(
		'CREATE TABLE IF NOT EXISTS __migrations (name TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)'
	);
	const applied = new Set((await rawQuery('SELECT name FROM __migrations')).map(([name]) => name));

	for (const [path, sql] of Object.entries(migrations).sort(([a], [b]) => a.localeCompare(b))) {
		const name = path.split('/').pop()!;

		if (applied.has(name)) {
			continue;
		}

		for (const statement of sql.split('--> statement-breakpoint')) {
			if (statement.trim()) {
				await rawQuery(statement);
			}
		}

		await rawQuery('INSERT INTO __migrations (name, applied_at) VALUES (?, ?)', [name, Date.now()]);
	}
}
